from pathlib import Path
p=Path('docs/system-design.md');s=p.read_text(encoding='utf-8');s=s.replace('手机竖屏改为 94px 三列信息条（立绘、身份技能、棋钟统计），行间距 8px，棋盘按屏宽、动态视口和安全区共同限高，优先一屏容纳全部对弈内容；手机身份行按内容占宽，姓名、段位和积分同行，移除多余外框但保留装备姓名牌','手机竖屏保留 94px 立绘占位，恢复大改前的两行信息卡；卡片左端插入立绘背后，身份／时间在上、统计／技能在下，整卡以米色／回合黄色及阴影反馈。行间距 8px，棋盘仍按屏宽、动态视口和安全区共同限高，优先一屏显示');p.write_text(s,encoding='utf-8')
p=Path('docs/system-design/06-ui-theme-mobile.md');s=p.read_text(encoding='utf-8');start=s.index('竖屏使用 94px 高的三列信息条');end=s.index('\n',start);s=s[:start]+'''竖屏信息卡按用户要求恢复为大改前的两行布局（portrait/meta/time 与 portrait/captures/skill）；`battle-paper-panels.css` 仅作用于非 mobile-room-screen，手机的 `player-clock-panel` 使用 display: contents，因此沿用原 timer、统计和技能样式。保留 94px 信息条、66px 出框立绘，独立卡片底板从左侧 48px 开始，约 18px 边缘藏在立绘下；底板使用米色／回合黄色及整卡阴影，文字从立绘列之外开始，不被覆盖。底板伪元素显式覆盖旧主题的 content/display/background 重置，立绘使用更高局部层级。视口仍为四行 max-content、8px 间距，棋盘使用屏宽和 dvh／安全区共同定尺寸，大屏优先一屏，短屏允许滚动。桌面分层布局保持不变。'''+s[end:];p.write_text(s,encoding='utf-8')
